		0.11239642 +
		1 /
			(+1.6132032 -
				0.68124379 * b_ +
				a_ *
					(+0.40370612 +
						0.90148123 * b_ +
						a_ *
							(-0.27087943 +
								0.6122399 * b_ +
								a_ *
									(+0.00299215 -
										0.45399568 * b_ -
										0.14661872 * a_))));

